-- Overwrites the text of every built-in page with the current site copy.
-- Status, hero image, video and menu settings are left untouched; pages created in the dashboard are not affected.
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `eyebrow` = VALUES(`eyebrow`),
  `intro` = VALUES(`intro`),
  `sections` = VALUES(`sections`),
  `updatedAt` = NOW(3);
