INSERT INTO `ContentPage` (`id`, `slug`, `title`, `eyebrow`, `intro`, `sections`, `status`, `publishedAt`, `createdAt`, `updatedAt`)
VALUES
(UUID(), 'about', 'About Godoma TTI', 'Our institute', 'Godoma Technical Training Institute is a public technical training institute in Vitengeni, Kilifi County, committed to equipping youth with practical, entrepreneurial and employable skills.', '[["Who we are","Godoma TTI is the first public sub-county technical training institute in Kilifi County. Since opening in 2016, the institute has provided accessible technical and vocational education and training for young people and working adults across the region."],["Our role in Kenya","The institute contributes to Kenya’s skills development agenda by preparing competent graduates for employment, self-employment, enterprise, innovation and further learning. Training combines classroom knowledge, practical workshop experience, digital literacy, industry exposure and responsible citizenship."],["Vision","To be a centre of excellence in technical training."],["Mission","To provide quality, relevant and accessible technical training for sustainable development."],["Core values","Respect, quality, excellence, integrity, discipline, equity and teamwork."],["Training environment","Godoma TTI offers a supportive learning environment with practical workshops, ICT laboratories, a library, student support services, co-curricular activities, industry engagement and dedicated teaching and non-teaching staff."],["Academic departments","The institute delivers training through Electrical and Electronics Engineering, Building and Civil Engineering, Computing and Informatics, Tourism and Hospitality, Mechanical Engineering, Fashion and Cosmetology, Agricultural Studies, and Business and Liberal Studies. Programmes include TVET CDACC Level 4, 5 and 6 courses and 3-month short courses, subject to current course offerings and entry requirements."],["Brief history","Godoma Technical Training Institute was commissioned in November 2016 and is located in Vitengeni near Kilifi County. The campus sits in a serene setting bordering the famous Dida Forest, where the welcoming local community promotes peaceful coexistence. The institute continues to grow as a centre for quality learning, research, innovation and practical skills development."],["Partners and quality assurance","Godoma TTI works within Kenya’s TVET system and engages with national education, examination, placement, loans and industrial training institutions, including TVETA, KNEC, KUCCPS, HELB and NITA."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'notice-board', 'Notice Board', 'Updates and announcements', 'Find the latest admissions notices, student updates, events and official institute information in one place.', '[["HELB TVET Loans & Bursaries","HELB finances TVET students in over 200 technical institutes. Eligible trainees in approved TVET CDACC programmes can apply for tuition and upkeep support through the official HELB channels."],["Motivational Talk","The Office of the Dean of Students invites staff and trainees to a talk on coronavirus, HIV/AIDS, drugs, mental health and discipline at GTTI Phase II."],["Service Charter","Read the Godoma TTI Service Charter in English and Kiswahili for information about our services, commitments and customer care standards."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'governance', 'Godoma TTI Governance', 'Leadership and accountability', 'Welcome to Godoma Technical Training Institute. Our Board of Governors is dedicated to creating an environment where hands-on learning meets modern industry standards. Through strong oversight, strategic resource management, and strategic partnerships, we ensure our institution equips every trainee with market-relevant skills to transform their lives and contribute to regional and national development.', '[["Message from the Chairperson","Welcome to Godoma Technical Training Institute. As Chairman of the Board of Governors, I am delighted to be part of Godoma’s journey towards achieving its vision of becoming a centre of excellence in technical training, research and business incubation. At Godoma, we are committed to providing accessible, quality, needs-based technical and vocational training that equips learners with practical, market-relevant skills to thrive in the national and global economy. Beyond preparing graduates for employment, we aim to nurture entrepreneurship, innovation and business creation, empowering our learners to create opportunities for themselves and others while contributing to sustainable livelihoods and economic development. As a Board, we are actively fulfilling our strategic oversight role to support the Institute in achieving its mission. We are committed to strengthening institutional governance, promoting sustainable growth, and ensuring that Godoma continues to improve the quality and relevance of its training while creating greater opportunities for our learners. Achieving this vision requires the collective effort of all stakeholders. We therefore welcome collaboration, ideas and constructive contributions from our students, staff, parents, industry partners, government agencies, development partners, alumni and the wider community. Our doors remain open to engagement and input from all those who share our aspirations for Godoma. I invite you all to join hands with the Board and Management in building a stronger, more responsive and sustainable institution — one that develops skilled, competent and innovative graduates who can contribute meaningfully to society and the economy.\\n\\nEmmanuel Kadenge Masha\\nChairman, Board of Governors\\nGodoma Technical Training Institute","An agricultural professional, agribusiness consultant and development practitioner. He holds a BSc in Agriculture and is pursuing a MA in Project Planning and Management from the University of Nairobi.\\n\\nHe has 13 years of professional experience, including seven years in government service and six years with non-governmental organizations, specializing in programme management, agricultural development and community empowerment.\\n\\nCurrently a full-time agribusiness consultant and farmer, he leads farmer empowerment and agricultural commercialization initiatives in Ganze Sub-County, with a focus on cashew farming, value addition and rural livelihoods.\\n\\nAs Chairman of the Board of Governors, he brings his experience in strategic leadership and community development to support Godoma TTI’s growth and its ambition to become a center of excellence in technical training, research and business incubation."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'administration', 'Administration', 'Supporting student success', 'Meet the offices responsible for leadership, academic delivery, trainee welfare and institute operations.', '[["Principal’s office","Provides institutional leadership, planning and quality assurance."],["Deputy Principal — Administration","Coordinates administration, operations, staff support and institutional services."],["Deputy Principal — Academics","Coordinates academic planning, training delivery, examinations and departmental performance."],["Registrar","Guides applicants through admission, registration, academic records and certification."],["Dean of Students","Supports trainee welfare, guidance, discipline and co-curricular life."],["Finance Office","Manages fees, financial records, budgeting and responsible stewardship of institute resources."],["Procurement Office","Coordinates transparent acquisition of goods and services in support of training and operations."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'deputy-principal-administration', 'Deputy Principal — Administration', 'Administration', 'The Deputy Principal’s Office coordinates academic and operational activities that keep training programmes running effectively.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'deputy-principal-academics', 'Deputy Principal — Academics / Training', 'Administration', 'Supporting relevant, practical and high-quality technical education for every trainee.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'finance', 'Finance Office', 'Administration', 'The Finance Office supports transparent financial management, fee administration, budgeting, financial records and responsible stewardship of institute resources.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'procurement', 'Procurement Office', 'Administration', 'The Procurement Office supports transparent, fair and accountable purchasing for Godoma Technical Training Institute.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'council-bog-chairperson', 'Council / BOG Chairperson', 'Administration', 'The Council and Board of Governors Chairperson provides strategic oversight and supports accountable leadership at Godoma Technical Training Institute.', '[["Strategic oversight","The Chairperson guides the Council and Board in setting priorities that strengthen teaching, training, governance and institutional development."],["Accountability","The office works with institute leadership to promote transparency, responsible stewardship and effective implementation of approved plans."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'principal-office', 'Principal Office', 'Administration', 'The Principal’s Office provides executive leadership for the institute and coordinates the delivery of quality technical training.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'deputy-principal-office', 'Deputy Principal Office', 'Administration', 'The Deputy Principal’s Office coordinates academic and operational activities that keep training programmes running effectively.', '[["Academic coordination","The office supports the planning and monitoring of teaching, examinations, timetables and departmental performance."],["Operations","The Deputy Principal works with staff and institute leadership to maintain efficient day-to-day academic operations."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'dean-of-students', 'Dean of Students', 'Administration', 'The Dean of Students supports trainee welfare, discipline, guidance and a positive campus experience.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'recognition-of-prior-learning', 'Recognition of Prior Learning (RPL)', 'Academics', 'Recognition of Prior Learning provides a pathway for experienced individuals to have skills and knowledge gained through work, life experience, informal learning, or previous training assessed and recognised.', '[["What is RPL?","RPL is an assessment process that identifies, documents, and evaluates a candidate’s existing competencies against the requirements of a recognised course or qualification. It focuses on what a candidate can demonstrate, not only where or how the learning was acquired."],["Who can apply?","RPL may support applicants and workers who have gained relevant skills through employment, enterprise, community service, apprenticeships, informal training, or other practical experience. Candidates should provide evidence of their experience and be ready to demonstrate their competence through the assessment process."],["The process","Applicants receive guidance on the relevant qualification, submit evidence, participate in counselling and assessment, and receive feedback on the outcome. Where gaps are identified, the institute may recommend targeted training before reassessment."],["Why RPL matters","RPL promotes access, mobility, lifelong learning, and fair recognition of practical skills while helping employers and industries access a more capable workforce. Contact the institute for current application requirements and assessment guidance."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'industrial-liaison-office', 'Industrial Liaison Office', 'Academics', 'It is my pleasure to serve as the Industry Liaison Officer at Godoma Technical Training Institute, fostering strong partnerships between the Institute and industry to promote skills development, dual training implementation, and employment opportunities for our students.', '[["Industry collaboration","At Godoma TTI, we are committed to aligning training with industry needs. Through collaboration with employers and industry stakeholders, we create opportunities for industrial attachment, internships, workplace experience, and career development, preparing our learners for the demands of the modern workplace."],["A message to our students and partners","I encourage our students to embrace these opportunities, build professional networks, and develop the practical skills needed to succeed in today’s competitive job market. I also invite industry partners to collaborate with Godoma TTI in nurturing talent and building a skilled, competent, and productive workforce."],["Join Godoma TTI","Your future career starts with the right skills! Enrol at Godoma TTI today and gain the practical training, industry exposure, and professional competencies you need to succeed. Choose Godoma TTI, build your skills, and turn your ambitions into reality."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'registrar-office', 'Registrar Office', 'Administration', '', '[["Admissions and registration","The office guides applicants through entry requirements, course selection, admission and registration procedures."],["Academic records","The Registrar maintains accurate trainee records and supports official communication on examinations, progression and certification."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'iqa', 'IQA (Internal Quality Assurance Office)', 'Academics', 'The objective of Technical and Vocational Education and Training (TVET) is to equip trainees with relevant skills and competencies for the world of work. At Godoma Technical Training Institute, quality assurance is central to the delivery of effective, relevant, and competency-based training.', '[["Quality assurance at Godoma TTI","The Internal Quality Assurance (IQA) Office coordinates quality assurance activities to ensure compliance with established training standards, institutional policies, and regulatory requirements. The office monitors training delivery and assessment, conducts internal quality audits, identifies areas for improvement, and promotes continuous enhancement of institutional processes and trainee learning outcomes."],["A culture of quality","Through collaboration with management, trainers, and other stakeholders, the office strives to foster a culture of quality, accountability, and excellence in training and service delivery."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'assessment-office', 'Assessment Office', 'Academics', 'The Assessment Office supports fair, reliable, and well-coordinated assessment processes that help trainees demonstrate the knowledge, skills, and competencies developed through their training.', '[]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'admissions', 'Admissions', 'Start your technical journey', 'Applications are open for TVET CDACC programmes at Levels 4, 5 and 6, and 3-month short courses, across our eight departments.', '[["Entry requirements","TVET CDACC programme entry requirements vary by level and course. Confirm the specific requirements for Levels 4, 5 and 6 and the open short courses with the Admissions Office."],["accommodation","Contact the institute for current information about accommodation and student support."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'funding', 'Student Funding in Kenya', 'Financial support for training', 'Information to help Godoma TTI trainees explore available funding options for technical and vocational education and training in Kenya.', '[["HELB TVET loans","Eligible Kenyan trainees in approved TVET programmes may apply for Higher Education Loans Board (HELB) TVET support. Depending on eligibility and the current funding cycle, support may contribute towards tuition and upkeep. Apply through the official HELB channels and provide accurate admission and identification details."],["TVET scholarships and bursaries","Students may also explore scholarships and bursaries offered through the Higher Education Financing portal, county governments, constituency offices, the National Government Constituencies Development Fund (NG-CDF), foundations, and other recognised sponsors. Availability, requirements, and deadlines vary by provider."],["How to prepare","Keep your admission letter, national identification details, KCSE or equivalent results, family and financial information, passport photos, and any documents requested by the funding provider ready. Apply early and retain copies or confirmation messages for your records."],["Important guidance","Funding is subject to the rules, assessment, and budgets of the relevant provider. Godoma TTI does not guarantee approval. Confirm current requirements and application deadlines directly through official government or funding-provider channels, and avoid paying unauthorised agents for funding applications."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'trainees', 'Trainee services', 'Everything you need on campus', 'Find the digital services, downloads and student activities that support your training experience.', '[["portal","Access student services, notices and academic information through the student portal."],["elearning","Continue learning beyond the classroom with digital course resources and guided study."],["downloads","Find admission letters, forms and student notices from the registry."],["aids-control","The Aids Control Unit provides information, prevention education and confidential support."],["events","Keep up with institute events, student activities and important dates."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'guidance-counselling', 'Guidance and Counselling', 'Trainee support', 'The Guidance and Counselling Office supports trainees through their academic journey, personal growth, and overall well-being in a caring and supportive environment.', '[["A supportive office","It is my pleasure to serve and support our students as the Head of Guidance and Counselling. I am committed to helping you navigate your academic journey, personal growth, and overall well-being in a caring and supportive environment."],["Always open to listen","My office is always open to listen, guide, and encourage you. Stay positive no matter the situation you are in and share the challenges with your friends as much as possible. Remember, seeking support is a sign of strength, and together we can overcome any challenge."],["Your well-being matters","Your well-being matters, your dreams are valid, and your success is our joy."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'library', 'Library', 'Learn beyond the classroom', 'The Godoma TTI library supports research, assignments and independent learning for every department.', '[["Library services","Access reference materials, course texts and a quiet environment for study."],["Opening hours","Visit the library notice board or contact the institute for the current timetable."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'downloads', 'Downloads', 'Resources and forms', 'Access useful institute resources, forms and notices for applicants, trainees and members of the Godoma TTI community.', '[["Admission resources","Download application guidance, entry requirement information and registration checklists before beginning your technical training journey."],["Trainee resources","Find student forms, service information and academic support resources to help you manage your training experience."],["Official notices","Keep up with official institute circulars, event notices and important updates published by the administration."],["Need help?","If you cannot find the resource you need, contact the Registrar Office or use the Contact Us page for assistance."]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3)),
(UUID(), 'contact', 'Contact Godoma TTI', 'We are here to help', 'Reach the institute for admissions guidance, course information, partnerships and general enquiries.', '[["Phone","+254 743 661 423"],["Email","godomatti.gtti@gmail.com"],["Address","Matanomane, Vitengeni Rd, Kilifi County, Kenya"]]', 'PUBLISHED', NOW(3), NOW(3), NOW(3))
